// Package migrations embeds the SQL migration files applied at startup.
package migrations

import "embed"

// FS contains the ordered .sql migrations.
//
//go:embed *.sql
var FS embed.FS

// Package store opens the SQLite database, applies migrations and seeds demo data.
package store

import (
	"database/sql"
	"errors"
	"fmt"
	"net/url"
	"os"
	"path/filepath"
	"strings"

	_ "modernc.org/sqlite"
)

// DB holds one serialized write pool and a concurrent read pool.
type DB struct {
	Write *sql.DB
	Read  *sql.DB
	Path  string
}

// Open creates or opens the SQLite database at path. WAL, foreign keys and a
// busy timeout are configured per connection; reads use a query-only pool.
func Open(path string) (*DB, error) {
	abs, err := filepath.Abs(path)
	if err != nil {
		return nil, fmt.Errorf("resolve database path: %w", err)
	}
	if err := os.MkdirAll(filepath.Dir(abs), 0o755); err != nil {
		return nil, fmt.Errorf("create database directory: %w", err)
	}

	pragmas := url.Values{}
	pragmas.Add("_pragma", "busy_timeout(10000)")
	pragmas.Add("_pragma", "foreign_keys(1)")
	pragmas.Add("_pragma", "journal_mode(WAL)")
	pragmas.Add("_pragma", "synchronous(NORMAL)")

	writeDSN := "file:" + filepath.ToSlash(abs) + "?" + pragmas.Encode() + "&_txlock=immediate"
	write, err := sql.Open("sqlite", writeDSN)
	if err != nil {
		return nil, fmt.Errorf("open write database: %w", err)
	}
	write.SetMaxOpenConns(1)
	write.SetMaxIdleConns(1)
	write.SetConnMaxLifetime(0)
	if err := write.Ping(); err != nil {
		write.Close()
		return nil, fmt.Errorf("ping write database: %w", err)
	}

	readPragmas := url.Values{}
	readPragmas.Add("_pragma", "busy_timeout(10000)")
	readPragmas.Add("_pragma", "foreign_keys(1)")
	readPragmas.Add("_pragma", "query_only(1)")
	readDSN := "file:" + filepath.ToSlash(abs) + "?" + readPragmas.Encode()
	read, err := sql.Open("sqlite", readDSN)
	if err != nil {
		write.Close()
		return nil, fmt.Errorf("open read database: %w", err)
	}
	read.SetMaxOpenConns(8)
	read.SetMaxIdleConns(8)
	read.SetConnMaxLifetime(0)
	if err := read.Ping(); err != nil {
		write.Close()
		read.Close()
		return nil, fmt.Errorf("ping read database: %w", err)
	}

	return &DB{Write: write, Read: read, Path: abs}, nil
}

// Close releases both pools.
func (db *DB) Close() error {
	return errors.Join(db.Read.Close(), db.Write.Close())
}

// IsBusy reports whether err is a transient SQLite lock/busy error.
func IsBusy(err error) bool {
	if err == nil {
		return false
	}
	msg := strings.ToLower(err.Error())
	return strings.Contains(msg, "sqlite_busy") ||
		strings.Contains(msg, "sqlite_locked") ||
		strings.Contains(msg, "database is locked") ||
		strings.Contains(msg, "database table is locked")
}

package store

import (
	"database/sql"
	"fmt"
	"io/fs"
	"sort"
	"strings"
	"time"

	"certadmin/migrations"
)

// Migrate applies embedded .sql migrations exactly once each.
func (db *DB) Migrate() error {
	_, err := db.Write.Exec(`CREATE TABLE IF NOT EXISTS schema_migrations (
		version INTEGER PRIMARY KEY,
		applied_at TEXT NOT NULL
	) STRICT`)
	if err != nil {
		return fmt.Errorf("create schema_migrations: %w", err)
	}

	entries, err := fs.ReadDir(migrations.FS, ".")
	if err != nil {
		return fmt.Errorf("read migrations: %w", err)
	}
	var names []string
	for _, entry := range entries {
		if !entry.IsDir() && strings.HasSuffix(entry.Name(), ".sql") {
			names = append(names, entry.Name())
		}
	}
	sort.Strings(names)

	for i, name := range names {
		version := i + 1
		var applied int
		if err := db.Write.QueryRow(`SELECT COUNT(*) FROM schema_migrations WHERE version = ?`, version).Scan(&applied); err != nil {
			return fmt.Errorf("check migration %s: %w", name, err)
		}
		if applied > 0 {
			continue
		}
		body, err := migrations.FS.ReadFile(name)
		if err != nil {
			return fmt.Errorf("read migration %s: %w", name, err)
		}
		tx, err := db.Write.Begin()
		if err != nil {
			return fmt.Errorf("begin migration %s: %w", name, err)
		}
		for _, stmt := range splitStatements(string(body)) {
			if _, err := tx.Exec(stmt); err != nil {
				tx.Rollback()
				return fmt.Errorf("apply migration %s: %w", name, err)
			}
		}
		if _, err := tx.Exec(`INSERT INTO schema_migrations (version, applied_at) VALUES (?, ?)`,
			version, time.Now().UTC().Format("2006-01-02T15:04:05.000Z")); err != nil {
			tx.Rollback()
			return fmt.Errorf("record migration %s: %w", name, err)
		}
		if err := tx.Commit(); err != nil {
			return fmt.Errorf("commit migration %s: %w", name, err)
		}
	}
	return nil
}

func splitStatements(body string) []string {
	parts := strings.Split(body, ";")
	out := make([]string, 0, len(parts))
	for _, part := range parts {
		if hasSQL(part) {
			out = append(out, strings.TrimSpace(part))
		}
	}
	return out
}

func hasSQL(part string) bool {
	for _, line := range strings.Split(part, "\n") {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "--") {
			continue
		}
		return true
	}
	return false
}

// SeedIfEmpty initializes the default demo data only when no tenant exists.
// Repeated startups therefore never reset user data.
func (db *DB) SeedIfEmpty() (bool, error) {
	var tenants int
	if err := db.Write.QueryRow(`SELECT COUNT(*) FROM tenants`).Scan(&tenants); err != nil {
		return false, fmt.Errorf("count tenants: %w", err)
	}
	if tenants > 0 {
		return false, nil
	}
	tx, err := db.Write.Begin()
	if err != nil {
		return false, fmt.Errorf("begin seed: %w", err)
	}
	if err := seedDefault(tx); err != nil {
		tx.Rollback()
		return false, fmt.Errorf("seed demo data: %w", err)
	}
	if err := tx.Commit(); err != nil {
		return false, fmt.Errorf("commit seed: %w", err)
	}
	return true, nil
}

func seedDefault(tx *sql.Tx) error {
	const insertTenant = `INSERT INTO tenants (id, code, name, timezone) VALUES (?, ?, ?, ?)`
	if _, err := tx.Exec(insertTenant, 1, "EAST", "East", "Australia/Sydney"); err != nil {
		return err
	}
	if _, err := tx.Exec(insertTenant, 2, "WEST", "West", "Australia/Perth"); err != nil {
		return err
	}

	const insertAdmin = `INSERT INTO admins (id, tenant_id, email) VALUES (?, ?, ?)`
	if _, err := tx.Exec(insertAdmin, 1, 1, "alice@east.test"); err != nil {
		return err
	}
	if _, err := tx.Exec(insertAdmin, 2, 2, "bob@west.test"); err != nil {
		return err
	}

	learners := []struct {
		id       int64
		tenantID int64
		name     string
	}{
		{1, 1, "Alex Lee"}, {2, 1, "Sam Chen"}, {3, 1, "Taylor Kim"}, {4, 1, "Morgan Wu"},
		{5, 2, "Alex Lee"}, {6, 2, "Sam Chen"}, {7, 2, "Taylor Kim"}, {8, 2, "Morgan Wu"},
	}
	for _, l := range learners {
		if _, err := tx.Exec(`INSERT INTO learners (id, tenant_id, name) VALUES (?, ?, ?)`, l.id, l.tenantID, l.name); err != nil {
			return err
		}
	}

	courses := []struct {
		id       int64
		tenantID int64
		title    string
	}{
		{1, 1, "Safety 101"}, {2, 1, "First Aid"},
		{3, 2, "Safety 101"}, {4, 2, "First Aid"},
	}
	for _, c := range courses {
		if _, err := tx.Exec(`INSERT INTO courses (id, tenant_id, title) VALUES (?, ?, ?)`, c.id, c.tenantID, c.title); err != nil {
			return err
		}
	}

	type enrollment struct {
		id         int64
		tenantID   int64
		courseID   int64
		learnerID  int64
		status     string
		completed  string
	}
	enrollments := []enrollment{
		{1, 1, 1, 1, "COMPLETED", "2026-01-09T00:00:00.000Z"},
		{2, 1, 1, 2, "INCOMPLETE", ""},
		{3, 1, 1, 3, "COMPLETED", "2026-01-08T00:00:00.000Z"},
		{4, 1, 1, 4, "COMPLETED", "2026-01-07T00:00:00.000Z"},
		{5, 1, 2, 1, "COMPLETED", "2026-01-09T00:00:00.000Z"},
		{6, 2, 3, 5, "COMPLETED", "2026-01-09T00:00:00.000Z"},
		{7, 2, 3, 6, "INCOMPLETE", ""},
		{8, 2, 3, 7, "COMPLETED", "2026-01-08T00:00:00.000Z"},
		{9, 2, 3, 8, "COMPLETED", "2026-01-07T00:00:00.000Z"},
		{10, 2, 4, 5, "COMPLETED", "2026-01-09T00:00:00.000Z"},
	}
	for _, e := range enrollments {
		var completed any
		if e.completed != "" {
			completed = e.completed
		}
		if _, err := tx.Exec(`INSERT INTO enrollments
			(id, tenant_id, course_id, learner_id, completion_status, completed_at)
			VALUES (?, ?, ?, ?, ?, ?)`,
			e.id, e.tenantID, e.courseID, e.learnerID, e.status, completed); err != nil {
			return err
		}
	}

	type certificate struct {
		id          int64
		tenantID    int64
		enrollment  int64
		courseID    int64
		learnerID   int64
		serial      string
		status      string
		issuedAt    string
		localDate   string
		issuedBy    int64
		revokedAt   any
		revokedBy   any
	}
	certificates := []certificate{
		{1, 2, 8, 3, 7, "CERT-WEST-TAYLOR-0001", "ACTIVE", "2026-01-10T13:30:00.000Z", "2026-01-10", 2, nil, nil},
		{2, 2, 9, 3, 8, "CERT-WEST-MORGAN-0001", "REVOKED", "2026-01-09T13:30:00.000Z", "2026-01-09", 2, "2026-01-10T00:00:00.000Z", 2},
		{3, 1, 3, 1, 3, "CERT-EAST-TAYLOR-0001", "ACTIVE", "2026-01-10T13:30:00.000Z", "2026-01-11", 1, nil, nil},
		{4, 1, 4, 1, 4, "CERT-EAST-MORGAN-0001", "REVOKED", "2026-01-09T13:30:00.000Z", "2026-01-10", 1, "2026-01-10T00:00:00.000Z", 1},
	}
	for _, c := range certificates {
		if _, err := tx.Exec(`INSERT INTO certificates
			(id, tenant_id, enrollment_id, course_id, learner_id, serial_number, status,
			 issued_at, issued_local_date, issued_by_admin_id, revoked_at, revoked_by_admin_id)
			VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
			c.id, c.tenantID, c.enrollment, c.courseID, c.learnerID, c.serial, c.status,
			c.issuedAt, c.localDate, c.issuedBy, c.revokedAt, c.revokedBy); err != nil {
			return err
		}
	}

	type audit struct {
		id        int64
		tenantID  int64
		certID    int64
		actorID   int64
		eventType string
		occurred  string
	}
	audits := []audit{
		{1, 2, 1, 2, "ISSUED", "2026-01-10T13:30:00.000Z"},
		{2, 2, 2, 2, "ISSUED", "2026-01-09T13:30:00.000Z"},
		{3, 2, 2, 2, "REVOKED", "2026-01-10T00:00:00.000Z"},
		{4, 1, 3, 1, "ISSUED", "2026-01-10T13:30:00.000Z"},
		{5, 1, 4, 1, "ISSUED", "2026-01-09T13:30:00.000Z"},
		{6, 1, 4, 1, "REVOKED", "2026-01-10T00:00:00.000Z"},
	}
	for _, a := range audits {
		if _, err := tx.Exec(`INSERT INTO audit_events
			(id, tenant_id, certificate_id, actor_admin_id, event_type, occurred_at)
			VALUES (?, ?, ?, ?, ?, ?)`,
			a.id, a.tenantID, a.certID, a.actorID, a.eventType, a.occurred); err != nil {
			return err
		}
	}
	return nil
}

// Package service implements authentication, certificate queries, issuance,
// revocation and CSV streaming on top of the SQLite store.
package service

import (
	"time"

	_ "time/tzdata"
)

// Actor is the authenticated administrator with the tenant resolved from the
// token. Clients can never choose tenantId themselves.
type Actor struct {
	AdminID    int64
	Email      string
	TenantID   int64
	TenantCode string
	TenantName string
	Timezone   string
	Location   *time.Location
}

type AdminRef struct {
	ID    int64  `json:"id"`
	Email string `json:"email"`
}

type TenantRef struct {
	ID       int64  `json:"id"`
	Code     string `json:"code"`
	Name     string `json:"name"`
	Timezone string `json:"timezone"`
}

type LearnerRef struct {
	ID   int64  `json:"id"`
	Name string `json:"name"`
}

type CourseRef struct {
	ID    int64  `json:"id"`
	Title string `json:"title"`
}

type MeResponse struct {
	Admin  AdminRef  `json:"admin"`
	Tenant TenantRef `json:"tenant"`
}

type Page[T any] struct {
	Items    []T   `json:"items"`
	Page     int   `json:"page"`
	PageSize int   `json:"pageSize"`
	Total    int64 `json:"total"`
}

type CertificateSummary struct {
	ID              int64  `json:"id"`
	SerialNumber    string `json:"serialNumber"`
	Status          string `json:"status"`
	IssuedAt        string `json:"issuedAt"`
	IssuedLocalDate string `json:"issuedLocalDate"`
}

type CertificateListItem struct {
	ID              int64      `json:"id"`
	SerialNumber    string     `json:"serialNumber"`
	Learner         LearnerRef `json:"learner"`
	Course          CourseRef  `json:"course"`
	Status          string     `json:"status"`
	IssuedAt        string     `json:"issuedAt"`
	IssuedLocalDate string     `json:"issuedLocalDate"`
}

type CertificateDetail struct {
	ID              int64      `json:"id"`
	SerialNumber    string     `json:"serialNumber"`
	Learner         LearnerRef `json:"learner"`
	Course          CourseRef  `json:"course"`
	Status          string     `json:"status"`
	IssuedAt        string     `json:"issuedAt"`
	IssuedLocalDate string     `json:"issuedLocalDate"`
	IssuedLocalAt   string     `json:"issuedLocalAt"`
	Timezone        string     `json:"timezone"`
	IssuedBy        AdminRef   `json:"issuedBy"`
	RevokedAt       *string    `json:"revokedAt"`
	RevokedBy       *AdminRef  `json:"revokedBy"`
}

type Eligibility struct {
	Eligible   bool    `json:"eligible"`
	ReasonCode *string `json:"reasonCode"`
}

type EnrollmentItem struct {
	ID                 int64               `json:"id"`
	Learner            LearnerRef          `json:"learner"`
	Course             CourseRef           `json:"course"`
	CompletionStatus   string              `json:"completionStatus"`
	CompletedAt        *string             `json:"completedAt"`
	Certificate        *CertificateSummary `json:"certificate"`
	IssuanceEligibility Eligibility         `json:"issuanceEligibility"`
}

type BulkLearnerResult struct {
	LearnerID    int64   `json:"learnerId"`
	LearnerName  string  `json:"learnerName"`
	Status       string  `json:"status"`
	ReasonCode   *string `json:"reasonCode"`
	CertificateID *int64 `json:"certificateId"`
	SerialNumber *string `json:"serialNumber"`
}

type BulkOperationResult struct {
	OperationID string               `json:"operationId"`
	CourseID    int64                `json:"courseId"`
	Status      string               `json:"status"`
	Total       int                  `json:"total"`
	Issued      int                  `json:"issued"`
	Skipped     int                  `json:"skipped"`
	Failed      int                  `json:"failed"`
	Results     []BulkLearnerResult  `json:"results"`
}

type RevocationResult struct {
	CertificateID int64    `json:"certificateId"`
	RevokedAt     string   `json:"revokedAt"`
	RevokedBy     AdminRef `json:"revokedBy"`
}

// CertificateFilter is shared by the list and CSV endpoints so both use the
// same tenant, search, filter and ordering semantics.
type CertificateFilter struct {
	Q         string
	Status    string
	CourseID  int64
	LearnerID int64
	SortBy    string
	SortOrder string
	Page      int
	PageSize  int
}

type CertificateCSVRow struct {
	LearnerName     string
	CourseTitle     string
	SerialNumber    string
	IssuedLocalDate string
}

package service

import (
	"crypto/rand"
	"encoding/hex"
	"errors"
	"fmt"
	"strings"
	"time"

	"certadmin/internal/store"
)

const utcLayout = "2006-01-02T15:04:05.000Z"

var (
	ErrUnauthenticated      = errors.New("unauthenticated")
	ErrNotFound             = errors.New("not found")
	ErrIdempotencyConflict  = errors.New("idempotency conflict")
	ErrBusy                 = errors.New("temporarily unavailable")
)

// Service owns all business operations and explicit SQL.
type Service struct {
	db *store.DB
	now func() time.Time
}

func New(db *store.DB) *Service {
	return &Service{db: db, now: time.Now}
}

func formatUTC(t time.Time) string {
	return t.UTC().Format(utcLayout)
}

func parseUTC(value string) (time.Time, error) {
	return time.Parse(utcLayout, value)
}

func localDate(t time.Time, loc *time.Location) string {
	return t.In(loc).Format("2006-01-02")
}

func localDateTime(t time.Time, loc *time.Location) string {
	return t.In(loc).Format("2006-01-02T15:04:05.000-07:00")
}

func mapDBError(err error) error {
	if err == nil {
		return nil
	}
	if store.IsBusy(err) {
		return ErrBusy
	}
	return err
}

// newUUID returns a lowercase UUID v4.
func newUUID() (string, error) {
	var b [16]byte
	if _, err := rand.Read(b[:]); err != nil {
		return "", err
	}
	b[6] = (b[6] & 0x0f) | 0x40
	b[8] = (b[8] & 0x3f) | 0x80
	var out [36]byte
	hex.Encode(out[0:8], b[0:4])
	out[8] = '-'
	hex.Encode(out[9:13], b[4:6])
	out[13] = '-'
	hex.Encode(out[14:18], b[6:8])
	out[18] = '-'
	hex.Encode(out[19:23], b[8:10])
	out[23] = '-'
	hex.Encode(out[24:36], b[10:16])
	return string(out[:]), nil
}

const crockford = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"

// newULID builds a lexicographically sortable ULID at time t.
func newULID(t time.Time) (string, error) {
	var raw [16]byte
	ms := uint64(t.UnixMilli())
	raw[0] = byte(ms >> 40)
	raw[1] = byte(ms >> 32)
	raw[2] = byte(ms >> 24)
	raw[3] = byte(ms >> 16)
	raw[4] = byte(ms >> 8)
	raw[5] = byte(ms)
	if _, err := rand.Read(raw[6:]); err != nil {
		return "", err
	}

	bits := make([]byte, 0, 128)
	for _, v := range raw {
		for i := 7; i >= 0; i-- {
			bits = append(bits, (v>>uint(i))&1)
		}
	}
	out := make([]byte, 26)
	out[0] = crockford[bitsValue(bits[0:3])]
	for i := 0; i < 25; i++ {
		out[i+1] = crockford[bitsValue(bits[3+i*5:3+(i+1)*5])]
	}
	return string(out), nil
}

func bitsValue(bits []byte) int {
	v := 0
	for _, bit := range bits {
		v = v<<1 | int(bit)
	}
	return v
}

// onlineSerial is the documented online issuance format:
// CERT-{TENANT}-{ULID}. Seed and large-dataset rows use separate deterministic
// prefixes so collisions are impossible by construction.
func onlineSerial(tenantCode string, t time.Time) (string, error) {
	id, err := newULID(t)
	if err != nil {
		return "", err
	}
	return "CERT-" + strings.ToUpper(tenantCode) + "-" + id, nil
}

// Authenticate resolves the fixed demo token to an administrator and tenant.
func (s *Service) Authenticate(ctx context.Context, token string) (*Actor, error) {
	email, ok := demoTokens[token]
	if !ok {
		return nil, ErrUnauthenticated
	}
	var actor Actor
	err := s.db.Read.QueryRowContext(ctx, `
		SELECT a.id, a.email, t.id, t.code, t.name, t.timezone
		FROM admins a
		JOIN tenants t ON t.id = a.tenant_id
		WHERE a.email = ?`, email).
		Scan(&actor.AdminID, &actor.Email, &actor.TenantID, &actor.TenantCode, &actor.TenantName, &actor.Timezone)
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return nil, ErrUnauthenticated
		}
		return nil, mapDBError(err)
	}
	loc, err := time.LoadLocation(actor.Timezone)
	if err != nil {
		return nil, fmt.Errorf("load timezone %q: %w", actor.Timezone, err)
	}
	actor.Location = loc
	return &actor, nil
}

var demoTokens = map[string]string{
	"demo-alice-token": "alice@east.test",
	"demo-bob-token":   "bob@west.test",
}

package service

import (
	"context"
	"database/sql"
	"errors"
	"fmt"
	"strings"
)

func (s *Service) Me(actor *Actor) MeResponse {
	return MeResponse{
		Admin: AdminRef{ID: actor.AdminID, Email: actor.Email},
		Tenant: TenantRef{
			ID:       actor.TenantID,
			Code:     actor.TenantCode,
			Name:     actor.TenantName,
			Timezone: actor.Timezone,
		},
	}
}

func (s *Service) ListCourses(ctx context.Context, tenantID int64, page, pageSize int) (Page[CourseRef], error) {
	out := Page[CourseRef]{Items: []CourseRef{}, Page: page, PageSize: pageSize}
	tx, err := s.db.Read.BeginTx(ctx, &sql.TxOptions{ReadOnly: true})
	if err != nil {
		return out, mapDBError(err)
	}
	defer tx.Rollback()

	if err := tx.QueryRowContext(ctx, `SELECT COUNT(*) FROM courses WHERE tenant_id = ?`, tenantID).Scan(&out.Total); err != nil {
		return out, mapDBError(err)
	}
	offset := int64(page-1) * int64(pageSize)
	rows, err := tx.QueryContext(ctx, `
		SELECT id, title FROM courses
		WHERE tenant_id = ?
		ORDER BY id ASC
		LIMIT ? OFFSET ?`, tenantID, pageSize, offset)
	if err != nil {
		return out, mapDBError(err)
	}
	defer rows.Close()
	for rows.Next() {
		var item CourseRef
		if err := rows.Scan(&item.ID, &item.Title); err != nil {
			return out, err
		}
		out.Items = append(out.Items, item)
	}
	return out, mapDBError(rows.Err())
}

// EnrollmentQuery carries the optional filters shared by both enrollment lists.
type EnrollmentQuery struct {
	CompletionStatus string
	CourseID         int64
	Page             int
	PageSize         int
}

func (s *Service) CourseEnrollments(ctx context.Context, tenantID, courseID int64, q EnrollmentQuery) (Page[EnrollmentItem], error) {
