func (s *Service) queryEnrollments(ctx context.Context, tx *sql.Tx, where string, args []any, out Page[EnrollmentItem]) (Page[EnrollmentItem], error) {
	countSQL := `SELECT COUNT(*) FROM enrollments e WHERE ` + where
	if err := tx.QueryRowContext(ctx, countSQL, args...).Scan(&out.Total); err != nil {
		return out, mapDBError(err)
	}

	offset := int64(out.Page-1) * int64(out.PageSize)
	listArgs := append(append([]any{}, args...), out.PageSize, offset)
	rows, err := tx.QueryContext(ctx, `
		SELECT e.id, e.completion_status, e.completed_at,
		       l.id, l.name,
		       co.id, co.title,
		       c.id, c.serial_number, c.status, c.issued_at, c.issued_local_date
		FROM enrollments e
		JOIN learners l ON l.tenant_id = e.tenant_id AND l.id = e.learner_id
		JOIN courses co ON co.tenant_id = e.tenant_id AND co.id = e.course_id
		LEFT JOIN certificates c ON c.tenant_id = e.tenant_id AND c.enrollment_id = e.id
		WHERE `+where+`
		ORDER BY e.id ASC
		LIMIT ? OFFSET ?`, listArgs...)
	if err != nil {
		return out, mapDBError(err)
	}
	defer rows.Close()

	for rows.Next() {
		var (
			item        EnrollmentItem
			completedAt sql.NullString
			certID      sql.NullInt64
			certSerial  sql.NullString
			certStatus  sql.NullString
			certIssued  sql.NullString
			certDate    sql.NullString
		)
		if err := rows.Scan(&item.ID, &item.CompletionStatus, &completedAt,
			&item.Learner.ID, &item.Learner.Name,
			&item.Course.ID, &item.Course.Title,
			&certID, &certSerial, &certStatus, &certIssued, &certDate); err != nil {
			return out, err
		}
		if completedAt.Valid {
			v := completedAt.String
			item.CompletedAt = &v
		}
		if certID.Valid {
			item.Certificate = &CertificateSummary{
				ID:              certID.Int64,
				SerialNumber:    certSerial.String,
				Status:          certStatus.String,
				IssuedAt:        certIssued.String,
				IssuedLocalDate: certDate.String,
			}
		}
		item.IssuanceEligibility = eligibility(item.CompletionStatus, item.Certificate)
		out.Items = append(out.Items, item)
	}
	return out, mapDBError(rows.Err())
}

func eligibility(completionStatus string, cert *CertificateSummary) Eligibility {
	if completionStatus != "COMPLETED" {
		reason := "COURSE_INCOMPLETE"
		return Eligibility{Eligible: false, ReasonCode: &reason}
	}
	if cert != nil {
		reason := "ALREADY_CERTIFIED"
		if cert.Status == "REVOKED" {
			reason = "CERTIFICATE_REVOKED"
		}
		return Eligibility{Eligible: false, ReasonCode: &reason}
	}
	return Eligibility{Eligible: true}
}

func (s *Service) ListCertificates(ctx context.Context, tenantID int64, f CertificateFilter) (Page[CertificateListItem], error) {
	out := Page[CertificateListItem]{Items: []CertificateListItem{}, Page: f.Page, PageSize: f.PageSize}
	where, args := certificateWhere(tenantID, f)

	tx, err := s.db.Read.BeginTx(ctx, &sql.TxOptions{ReadOnly: true})
	if err != nil {
		return out, mapDBError(err)
	}
	defer tx.Rollback()

	countSQL := `SELECT COUNT(*) FROM certificates c
		JOIN learners l ON l.tenant_id = c.tenant_id AND l.id = c.learner_id
		WHERE ` + where
	if err := tx.QueryRowContext(ctx, countSQL, args...).Scan(&out.Total); err != nil {
		return out, mapDBError(err)
	}

	listArgs := append(append([]any{}, args...), f.PageSize, int64(f.Page-1)*int64(f.PageSize))
	rows, err := tx.QueryContext(ctx, `
		SELECT c.id, c.serial_number, c.status, c.issued_at, c.issued_local_date,
		       l.id, l.name, co.id, co.title
		FROM certificates c
		JOIN learners l ON l.tenant_id = c.tenant_id AND l.id = c.learner_id
		JOIN courses co ON co.tenant_id = c.tenant_id AND co.id = c.course_id
		WHERE `+where+`
		ORDER BY `+certificateOrder(f)+`
		LIMIT ? OFFSET ?`, listArgs...)
	if err != nil {
		return out, mapDBError(err)
	}
	defer rows.Close()

	for rows.Next() {
		var item CertificateListItem
		if err := rows.Scan(&item.ID, &item.SerialNumber, &item.Status, &item.IssuedAt, &item.IssuedLocalDate,
			&item.Learner.ID, &item.Learner.Name, &item.Course.ID, &item.Course.Title); err != nil {
			return out, err
		}
		out.Items = append(out.Items, item)
	}
	return out, mapDBError(rows.Err())
}

func certificateWhere(tenantID int64, f CertificateFilter) (string, []any) {
	where := []string{"c.tenant_id = ?"}
	args := []any{tenantID}
	if f.Q != "" {
		pattern := "%" + escapeLike(f.Q) + "%"
		where = append(where, `(l.name LIKE ? ESCAPE '\' OR c.serial_number LIKE ? ESCAPE '\')`)
		args = append(args, pattern, pattern)
	}
	if f.Status != "" {
		where = append(where, "c.status = ?")
		args = append(args, f.Status)
	}
	if f.CourseID > 0 {
		where = append(where, "c.course_id = ?")
		args = append(args, f.CourseID)
	}
	if f.LearnerID > 0 {
		where = append(where, "c.learner_id = ?")
		args = append(args, f.LearnerID)
	}
	return strings.Join(where, " AND "), args
}

func certificateOrder(f CertificateFilter) string {
	direction := "ASC"
	if strings.EqualFold(f.SortOrder, "desc") {
		direction = "DESC"
	}
	var key string
	switch f.SortBy {
	case "learnerName":
		key = "l.name"
	case "serialNumber":
		key = "c.serial_number"
	default:
		key = "c.issued_local_date"
	}
	// certificate.id ASC is always the deterministic tie-breaker, even when the
	// primary order is descending (A6 export stability).
	return key + " " + direction + ", c.id ASC"
}

func escapeLike(value string) string {
	replacer := strings.NewReplacer(`\`, `\\`, `%`, `\%`, `_`, `\_`)
	return replacer.Replace(value)
}

func (s *Service) CertificateDetail(ctx context.Context, actor *Actor, certificateID int64) (CertificateDetail, error) {
	var (
		out          CertificateDetail
		revokedAt    sql.NullString
		revokedID    sql.NullInt64
		revokedEmail sql.NullString
	)
	err := s.db.Read.QueryRowContext(ctx, `
		SELECT c.id, c.serial_number, c.status, c.issued_at, c.issued_local_date,
		       l.id, l.name, co.id, co.title,
		       ia.id, ia.email,
		       c.revoked_at, ra.id, ra.email
		FROM certificates c
		JOIN learners l ON l.tenant_id = c.tenant_id AND l.id = c.learner_id
		JOIN courses co ON co.tenant_id = c.tenant_id AND co.id = c.course_id
		JOIN admins ia ON ia.tenant_id = c.tenant_id AND ia.id = c.issued_by_admin_id
		LEFT JOIN admins ra ON ra.tenant_id = c.tenant_id AND ra.id = c.revoked_by_admin_id
		WHERE c.tenant_id = ? AND c.id = ?`, actor.TenantID, certificateID).
		Scan(&out.ID, &out.SerialNumber, &out.Status, &out.IssuedAt, &out.IssuedLocalDate,
			&out.Learner.ID, &out.Learner.Name, &out.Course.ID, &out.Course.Title,
			&out.IssuedBy.ID, &out.IssuedBy.Email,
			&revokedAt, &revokedID, &revokedEmail)
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return out, ErrNotFound
		}
		return out, mapDBError(err)
	}
	issued, err := parseUTC(out.IssuedAt)
	if err != nil {
		return out, fmt.Errorf("parse issued_at: %w", err)
	}
	out.IssuedLocalAt = localDateTime(issued, actor.Location)
	out.Timezone = actor.Timezone
	if revokedAt.Valid {
		value := revokedAt.String
		out.RevokedAt = &value
		out.RevokedBy = &AdminRef{ID: revokedID.Int64, Email: revokedEmail.String}
	}
	return out, nil
}

package service

import (
	"context"
	"crypto/sha256"
	"database/sql"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"strings"
	"time"
)

// BulkIssue performs a synchronous idempotent issuance for every enrollment in
// the course. The returned bytes are the stored response, so replays are
// byte-identical to the first response.
func (s *Service) BulkIssue(ctx context.Context, actor *Actor, courseID int64, idempotencyKey string) ([]byte, bool, error) {
	requestJSON := fmt.Sprintf(`{"courseId":%d}`, courseID)
	sum := sha256.Sum256([]byte(requestJSON))
	requestHash := hex.EncodeToString(sum[:])

	tx, err := s.db.Write.BeginTx(ctx, nil)
	if err != nil {
		return nil, false, mapDBError(err)
	}
	defer tx.Rollback()

	var exists int
	if err := tx.QueryRowContext(ctx, `SELECT 1 FROM courses WHERE tenant_id = ? AND id = ?`,
		actor.TenantID, courseID).Scan(&exists); err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return nil, false, ErrNotFound
		}
		return nil, false, mapDBError(err)
	}

	var storedHash, storedJSON string
	err = tx.QueryRowContext(ctx, `
		SELECT request_hash, response_json FROM bulk_operations
		WHERE tenant_id = ? AND actor_admin_id = ? AND idempotency_key = ?`,
		actor.TenantID, actor.AdminID, idempotencyKey).Scan(&storedHash, &storedJSON)
	if err == nil {
		if storedHash != requestHash {
			return nil, false, ErrIdempotencyConflict
		}
		return []byte(storedJSON), false, nil
	}
	if !errors.Is(err, sql.ErrNoRows) {
		return nil, false, mapDBError(err)
	}

	started := s.now().UTC().Truncate(time.Millisecond)
	operationID, err := newUUID()
	if err != nil {
		return nil, false, err
	}

	type enrollmentRow struct {
		id          int64
		learnerID   int64
		learnerName string
		completion  string
		certID      sql.NullInt64
		serial      sql.NullString
		certStatus  sql.NullString
	}
	rows, err := tx.QueryContext(ctx, `
		SELECT e.id, e.learner_id, l.name, e.completion_status,
		       c.id, c.serial_number, c.status
		FROM enrollments e
		JOIN learners l ON l.tenant_id = e.tenant_id AND l.id = e.learner_id
		LEFT JOIN certificates c ON c.tenant_id = e.tenant_id AND c.enrollment_id = e.id
		WHERE e.tenant_id = ? AND e.course_id = ?
		ORDER BY e.learner_id ASC`, actor.TenantID, courseID)
	if err != nil {
		return nil, false, mapDBError(err)
	}
	var enrollments []enrollmentRow
	for rows.Next() {
		var e enrollmentRow
		if err := rows.Scan(&e.id, &e.learnerID, &e.learnerName, &e.completion,
			&e.certID, &e.serial, &e.certStatus); err != nil {
			rows.Close()
			return nil, false, err
		}
		enrollments = append(enrollments, e)
	}
	if err := rows.Err(); err != nil {
		rows.Close()
		return nil, false, mapDBError(err)
	}
	rows.Close()

	result := BulkOperationResult{
		OperationID: operationID,
		CourseID:    courseID,
		Status:      "COMPLETED",
		Total:       len(enrollments),
		Results:     make([]BulkLearnerResult, 0, len(enrollments)),
	}

	issuedAt := formatUTC(started)
	localDateValue := localDate(started, actor.Location)

	for _, e := range enrollments {
		entry := BulkLearnerResult{LearnerID: e.learnerID, LearnerName: e.learnerName}
		switch {
		case e.completion != "COMPLETED":
			entry.Status = "skipped"
			entry.ReasonCode = stringPtr("COURSE_INCOMPLETE")
			result.Skipped++
			result.Results = append(result.Results, entry)

		case e.certID.Valid && e.certStatus.String == "ACTIVE":
			entry.Status = "skipped"
			entry.ReasonCode = stringPtr("ALREADY_CERTIFIED")
			id := e.certID.Int64
			serial := e.serial.String
			entry.CertificateID = &id
			entry.SerialNumber = &serial
			result.Skipped++
			result.Results = append(result.Results, entry)

		case e.certID.Valid && e.certStatus.String == "REVOKED":
			entry.Status = "skipped"
			entry.ReasonCode = stringPtr("CERTIFICATE_REVOKED")
			id := e.certID.Int64
			serial := e.serial.String
			entry.CertificateID = &id
			entry.SerialNumber = &serial
			result.Skipped++
			result.Results = append(result.Results, entry)

		default:
			serial, err := onlineSerial(actor.TenantCode, started)
			if err != nil {
				return nil, false, err
			}
			if _, err := tx.ExecContext(ctx, `SAVEPOINT learner_issue`); err != nil {
				return nil, false, mapDBError(err)
			}
			res, insertErr := tx.ExecContext(ctx, `
				INSERT INTO certificates
					(tenant_id, enrollment_id, course_id, learner_id, serial_number, status,
					 issued_at, issued_local_date, issued_by_admin_id, bulk_operation_id)
				VALUES (?, ?, ?, ?, ?, 'ACTIVE', ?, ?, ?, ?)`,
				actor.TenantID, e.id, courseID, e.learnerID, serial, issuedAt, localDateValue,
				actor.AdminID, operationID)
			if insertErr == nil {
				var certificateID int64
				certificateID, insertErr = res.LastInsertId()
				if insertErr == nil {
					_, insertErr = tx.ExecContext(ctx, `INSERT INTO audit_events
						(tenant_id, certificate_id, actor_admin_id, event_type, occurred_at)
						VALUES (?, ?, ?, 'ISSUED', ?)`,
						actor.TenantID, certificateID, actor.AdminID, issuedAt)
					if insertErr == nil {
						entry.Status = "issued"
						entry.CertificateID = &certificateID
						entry.SerialNumber = &serial
						result.Issued++
					}
				}
			}
			if insertErr != nil {
				if _, rbErr := tx.ExecContext(ctx, `ROLLBACK TO learner_issue`); rbErr != nil {
					return nil, false, mapDBError(rbErr)
				}
				if _, relErr := tx.ExecContext(ctx, `RELEASE learner_issue`); relErr != nil {
					return nil, false, mapDBError(relErr)
				}
				if !isConstraintError(insertErr) {
					return nil, false, mapDBError(insertErr)
				}
				entry.Status = "failed"
				entry.ReasonCode = stringPtr("ISSUANCE_ERROR")
				entry.CertificateID = nil
				entry.SerialNumber = nil
				result.Failed++
			} else {
				if _, err := tx.ExecContext(ctx, `RELEASE learner_issue`); err != nil {
					return nil, false, mapDBError(err)
				}
			}
			result.Results = append(result.Results, entry)
		}
	}

	completed := s.now().UTC().Truncate(time.Millisecond)
	if completed.Before(started) {
		completed = started
	}
	responseJSON, err := json.Marshal(result)
	if err != nil {
		return nil, false, err
	}
	if _, err := tx.ExecContext(ctx, `
		INSERT INTO bulk_operations
			(id, tenant_id, actor_admin_id, course_id, idempotency_key, request_hash,
			 request_json, response_json, started_at, completed_at)
		VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
		operationID, actor.TenantID, actor.AdminID, courseID, idempotencyKey,
		requestHash, requestJSON, string(responseJSON), formatUTC(started), formatUTC(completed)); err != nil {
		return nil, false, mapDBError(err)
	}
	if err := tx.Commit(); err != nil {
		return nil, false, mapDBError(err)
	}
	return responseJSON, true, nil
}

func stringPtr(value string) *string {
	return &value
}

func isConstraintError(err error) bool {
	return strings.Contains(strings.ToLower(err.Error()), "constraint failed") ||
		strings.Contains(strings.ToLower(err.Error()), "constraint violation")
}

package service

import (
	"context"
	"database/sql"
	"errors"
)

// Revoke creates the singleton revocation record. First ACTIVE -> REVOKED is
// created=true (HTTP 201); an already REVOKED certificate returns its original
// revocation data with created=false (HTTP 200).
func (s *Service) Revoke(ctx context.Context, actor *Actor, certificateID int64) (RevocationResult, bool, error) {
	var out RevocationResult
	tx, err := s.db.Write.BeginTx(ctx, nil)
	if err != nil {
		return out, false, mapDBError(err)
	}
	defer tx.Rollback()

	var (
		status       string
		revokedAt    sql.NullString
		revokedByID  sql.NullInt64
		revokedEmail sql.NullString
	)
	err = tx.QueryRowContext(ctx, `
		SELECT c.status, c.revoked_at, ra.id, ra.email
		FROM certificates c
		LEFT JOIN admins ra ON ra.tenant_id = c.tenant_id AND ra.id = c.revoked_by_admin_id
		WHERE c.tenant_id = ? AND c.id = ?`, actor.TenantID, certificateID).
		Scan(&status, &revokedAt, &revokedByID, &revokedEmail)
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return out, false, ErrNotFound
		}
		return out, false, mapDBError(err)
	}

	if status == "REVOKED" {
		out = RevocationResult{
			CertificateID: certificateID,
			RevokedAt:     revokedAt.String,
			RevokedBy:     AdminRef{ID: revokedByID.Int64, Email: revokedEmail.String},
		}
		return out, false, nil
	}

	now := formatUTC(s.now().UTC().Truncate(millisecond))
	res, err := tx.ExecContext(ctx, `
		UPDATE certificates
		SET status = 'REVOKED', revoked_at = ?, revoked_by_admin_id = ?
		WHERE tenant_id = ? AND id = ? AND status = 'ACTIVE'`,
		now, actor.AdminID, actor.TenantID, certificateID)
	if err != nil {
		return out, false, mapDBError(err)
	}
	affected, err := res.RowsAffected()
	if err != nil {
		return out, false, mapDBError(err)
	}
	if affected != 1 {
		return out, false, ErrBusy
	}
	if _, err := tx.ExecContext(ctx, `INSERT INTO audit_events
		(tenant_id, certificate_id, actor_admin_id, event_type, occurred_at)
		VALUES (?, ?, ?, 'REVOKED', ?)`,
		actor.TenantID, certificateID, actor.AdminID, now); err != nil {
		return out, false, mapDBError(err)
	}
	if err := tx.Commit(); err != nil {
		return out, false, mapDBError(err)
	}
	out = RevocationResult{
		CertificateID: certificateID,
		RevokedAt:     now,
		RevokedBy:     AdminRef{ID: actor.AdminID, Email: actor.Email},
	}
	return out, true, nil
}

package service

import (
	"context"
	"database/sql"
)

// StreamCertificates runs one consistent read transaction and emits every
// matching row in the same order as the list endpoint. start is called after
// the query has produced its first row but before any row is emitted; if the
// query itself fails, start is never called and the handler can still send a
// JSON error. Errors returned after start must abort the HTTP connection.
func (s *Service) StreamCertificates(
	ctx context.Context,
	tenantID int64,
	f CertificateFilter,
	start func(),
	emit func(CertificateCSVRow) error,
) error {
	where, args := certificateWhere(tenantID, f)
	tx, err := s.db.Read.BeginTx(ctx, &sql.TxOptions{ReadOnly: true})
	if err != nil {
		return mapDBError(err)
	}
	defer tx.Rollback()

	rows, err := tx.QueryContext(ctx, `
		SELECT l.name, co.title, c.serial_number, c.issued_local_date
		FROM certificates c
		JOIN learners l ON l.tenant_id = c.tenant_id AND l.id = c.learner_id
		JOIN courses co ON co.tenant_id = c.tenant_id AND co.id = c.course_id
		WHERE `+where+`
		ORDER BY `+certificateOrder(f), args...)
	if err != nil {
		return mapDBError(err)
	}
	defer rows.Close()

	hasRow := rows.Next()
	if err := rows.Err(); err != nil {
		return mapDBError(err)
	}
	start()
	for hasRow {
		var row CertificateCSVRow
		if err := rows.Scan(&row.LearnerName, &row.CourseTitle, &row.SerialNumber, &row.IssuedLocalDate); err != nil {
			return err
		}
		if err := emit(row); err != nil {
			return err
		}
		hasRow = rows.Next()
	}
	return mapDBError(rows.Err())
}

package httpapi

import (
	"errors"
	"log"
	"net/http"

	"certadmin/internal/service"

	"github.com/gin-gonic/gin"
)

type errorDetail struct {
	Field  string `json:"field"`
	Reason string `json:"reason"`
}

type apiError struct {
	Status  int
	Code    string
	Message string
	Details []errorDetail
}

func (e *apiError) Error() string { return e.Code + ": " + e.Message }

func badRequest(message, field, reason string) *apiError {
	e := &apiError{Status: http.StatusBadRequest, Code: "INVALID_ARGUMENT", Message: message}
	if field != "" {
		e.Details = []errorDetail{{Field: field, Reason: reason}}
	}
	return e
}

func unsupportedMedia() *apiError {
	return &apiError{
		Status:  http.StatusUnsupportedMediaType,
		Code:    "UNSUPPORTED_MEDIA_TYPE",
		Message: "非空请求体必须使用 application/json",
	}
}

func unauthorized(message string) *apiError {
	return &apiError{Status: http.StatusUnauthorized, Code: "UNAUTHENTICATED", Message: message}
}

func (s *Server) writeError(c *gin.Context, e *apiError) {
	if c.Writer.Written() {
		return
	}
	if e.Status == http.StatusUnauthorized {
		c.Header("WWW-Authenticate", `Bearer realm="certificate-admin"`)
	}
	if e.Status == http.StatusServiceUnavailable {
		c.Header("Retry-After", "1")
	}
	body := gin.H{
		"error": gin.H{
			"code":      e.Code,
			"message":   e.Message,
			"requestId": requestID(c),
			"details":   e.Details,
		},
	}
	if len(e.Details) == 0 {
		body["error"].(gin.H)["details"] = nil
	}
	c.AbortWithStatusJSON(e.Status, body)
}

func (s *Server) fail(c *gin.Context, err error) {
	switch {
	case errors.Is(err, service.ErrNotFound):
		s.writeError(c, &apiError{Status: http.StatusNotFound, Code: "NOT_FOUND", Message: "资源不存在"})
	case errors.Is(err, service.ErrIdempotencyConflict):
		s.writeError(c, &apiError{
			Status:  http.StatusConflict,
			Code:    "IDEMPOTENCY_CONFLICT",
			Message: "该幂等键已用于不同的请求",
			Details: []errorDetail{{Field: "Idempotency-Key", Reason: "REQUEST_MISMATCH"}},
		})
	case errors.Is(err, service.ErrBusy):
		s.writeError(c, &apiError{Status: http.StatusServiceUnavailable, Code: "TEMPORARILY_UNAVAILABLE", Message: "数据库暂时繁忙，请重试"})
	case errors.Is(err, service.ErrUnauthenticated):
		s.writeError(c, unauthorized("身份凭证无效或缺失"))
	default:
		log.Printf("request %s failed: %v", requestID(c), err)
		s.writeError(c, &apiError{Status: http.StatusInternalServerError, Code: "INTERNAL_ERROR", Message: "服务器内部错误"})
	}
}

package httpapi

import (
	"crypto/rand"
	"encoding/hex"
	"errors"
	"log"
	"net/http"
	"strings"

	"certadmin/internal/service"

	"github.com/gin-gonic/gin"
)

const actorKey = "actor"
const requestIDKey = "requestId"

func requestID(c *gin.Context) string {
	if value, ok := c.Get(requestIDKey); ok {
		return value.(string)
	}
	return ""
}

func requestIDMiddleware() gin.HandlerFunc {
	return func(c *gin.Context) {
		var raw [8]byte
		if _, err := rand.Read(raw[:]); err != nil {
			raw = [8]byte{0, 0, 0, 0, 0, 0, 0, 1}
		}
		id := "req-" + hex.EncodeToString(raw[:])
		c.Set(requestIDKey, id)
		c.Header("X-Request-Id", id)
		c.Header("Cache-Control", "no-store")
		c.Next()
	}
}

// recoveryMiddleware converts panics to JSON 500s but lets
// http.ErrAbortHandler pass through so a broken CSV stream closes the
// connection instead of looking like a successful download.
func recoveryMiddleware() gin.HandlerFunc {
	return func(c *gin.Context) {
		defer func() {
			if recovered := recover(); recovered != nil {
				if recovered == http.ErrAbortHandler {
					panic(recovered)
				}
				log.Printf("request %s panic: %v", requestID(c), recovered)
				if !c.Writer.Written() {
					s := &Server{}
					s.writeError(c, &apiError{
						Status:  http.StatusInternalServerError,
						Code:    "INTERNAL_ERROR",
						Message: "服务器内部错误",
					})
				} else {
					c.Abort()
				}
			}
		}()
		c.Next()
	}
}

func (s *Server) authMiddleware() gin.HandlerFunc {
	return func(c *gin.Context) {
		values := c.Request.Header.Values("Authorization")
		if len(values) != 1 {
			s.writeError(c, unauthorized("身份凭证无效或缺失"))
			return
		}
		parts := strings.SplitN(values[0], " ", 2)
		if len(parts) != 2 || !strings.EqualFold(parts[0], "Bearer") || strings.TrimSpace(parts[1]) == "" {
			s.writeError(c, unauthorized("身份凭证无效或缺失"))
			return
		}
		actor, err := s.svc.Authenticate(c.Request.Context(), strings.TrimSpace(parts[1]))
		if err != nil {
			if errors.Is(err, service.ErrUnauthenticated) {
				s.writeError(c, unauthorized("身份凭证无效或缺失"))
				return
			}
			s.fail(c, err)
			return
		}
		c.Set(actorKey, actor)
		c.Next()
	}
}

func actorFrom(c *gin.Context) *service.Actor {
	value, _ := c.Get(actorKey)
	actor, _ := value.(*service.Actor)
	return actor
}

package httpapi

import (
	"bytes"
	"encoding/json"
	"io"
	"mime"
	"net/http"
	"net/url"
	"regexp"
	"strconv"
	"strings"

	"certadmin/internal/service"

	"github.com/gin-gonic/gin"
)

var (
	pathIDPattern = regexp.MustCompile(`^[1-9][0-9]*$`)
	idemPattern   = regexp.MustCompile(`^[A-Za-z0-9_-]{1,128}$`)
)

func parseQuery(c *gin.Context, allowed ...string) (url.Values, *apiError) {
	values, err := url.ParseQuery(c.Request.URL.RawQuery)
	if err != nil {
		return nil, badRequest("查询参数格式错误", "", "")
	}
	set := make(map[string]struct{}, len(allowed))
	for _, name := range allowed {
		set[name] = struct{}{}
	}
	for key, list := range values {
		if _, ok := set[key]; !ok {
			return nil, badRequest("未知查询参数", key, "UNKNOWN_PARAMETER")
		}
		if len(list) > 1 {
			return nil, badRequest("查询参数不能重复", key, "DUPLICATE_PARAMETER")
		}
	}
	return values, nil
}

func parsePathID(c *gin.Context, name string) (int64, *apiError) {
	raw := c.Param(name)
	if !pathIDPattern.MatchString(raw) {
		return 0, badRequest("路径 ID 必须是正整数", name, "INVALID_ID")
	}
	value, err := strconv.ParseInt(raw, 10, 64)
	if err != nil {
		return 0, badRequest("路径 ID 超出范围", name, "INVALID_ID")
	}
	return value, nil
}

func stringParam(values url.Values, name string) (string, bool) {
	list, ok := values[name]
	if !ok {
		return "", false
	}
	return list[0], true
}

func positiveIntParam(values url.Values, name string) (int64, bool, *apiError) {
	raw, ok := stringParam(values, name)
	if !ok {
		return 0, false, nil
	}
	if !pathIDPattern.MatchString(raw) {
		return 0, true, badRequest("必须是正整数", name, "INVALID_INTEGER")
	}
	value, err := strconv.ParseInt(raw, 10, 64)
	if err != nil {
		return 0, true, badRequest("整数超出范围", name, "INVALID_INTEGER")
	}
	return value, true, nil
}

func pageParams(values url.Values) (int, int, *apiError) {
	page, pageSize := 1, 20
	if raw, ok := stringParam(values, "page"); ok {
		value, err := strconv.Atoi(raw)
		if err != nil || value < 1 || value > 1_000_000_000 {
			return 0, 0, badRequest("page 必须是正整数", "page", "INVALID_PAGE")
		}
		page = value
	}
	if raw, ok := stringParam(values, "pageSize"); ok {
		value, err := strconv.Atoi(raw)
		if err != nil || value < 1 || value > 100 {
			return 0, 0, badRequest("pageSize 必须在 1–100 之间", "pageSize", "INVALID_PAGE_SIZE")
		}
		pageSize = value
	}
	return page, pageSize, nil
}

func parseCompletion(values url.Values) (string, *apiError) {
	value, ok := stringParam(values, "completionStatus")
	if !ok {
		return "", nil
	}
	if value != "INCOMPLETE" && value != "COMPLETED" {
		return "", badRequest("completionStatus 只能是 INCOMPLETE 或 COMPLETED", "completionStatus", "INVALID_ENUM")
	}
	return value, nil
}

func parseCertificateFilter(c *gin.Context, allowPaging bool) (service.CertificateFilter, *apiError) {
	var f service.CertificateFilter
	allowed := []string{"q", "status", "courseId", "learnerId", "sortBy", "sortOrder"}
	if allowPaging {
		allowed = append(allowed, "page", "pageSize")
	}
	values, aerr := parseQuery(c, allowed...)
	if aerr != nil {
		return f, aerr
	}

	f.Q = strings.TrimSpace(c.Query("q"))
	if status, ok := stringParam(values, "status"); ok {
		if status != "ACTIVE" && status != "REVOKED" {
			return f, badRequest("status 只能是 ACTIVE 或 REVOKED", "status", "INVALID_ENUM")
		}
		f.Status = status
	}
	courseID, _, aerr := positiveIntParam(values, "courseId")
	if aerr != nil {
		return f, aerr
	}
	f.CourseID = courseID
	learnerID, _, aerr := positiveIntParam(values, "learnerId")
	if aerr != nil {
		return f, aerr
	}
	f.LearnerID = learnerID

	f.SortBy = "issuedLocalDate"
	if sortBy, ok := stringParam(values, "sortBy"); ok {
		switch sortBy {
		case "learnerName", "serialNumber", "issuedLocalDate":
			f.SortBy = sortBy
		default:
			return f, badRequest("不支持的排序字段", "sortBy", "INVALID_SORT")
		}
	}
	defaultOrder := "desc"
	if f.SortBy != "issuedLocalDate" {
		defaultOrder = "asc"
	}
	f.SortOrder = defaultOrder
	if sortOrder, ok := stringParam(values, "sortOrder"); ok {
		if sortOrder != "asc" && sortOrder != "desc" {
			return f, badRequest("sortOrder 只能是 asc 或 desc", "sortOrder", "INVALID_SORT")
		}
		f.SortOrder = sortOrder
	}

	f.Page, f.PageSize, aerr = pageParams(values)
	if aerr != nil {
		return f, aerr
	}
	return f, nil
}

func idempotencyKey(c *gin.Context) (string, *apiError) {
	values := c.Request.Header.Values("Idempotency-Key")
	if len(values) != 1 || !idemPattern.MatchString(values[0]) {
		return "", badRequest("Idempotency-Key 必须是 1–128 位 [A-Za-z0-9_-] 且只能出现一次", "Idempotency-Key", "INVALID_IDEMPOTENCY_KEY")
	}
	return values[0], nil
}

// validateEmptyJSONBody enforces the contract's optional, member-free body.
// Empty bodies are allowed; non-empty bodies must be an application/json object
// with no members at all.
func validateEmptyJSONBody(c *gin.Context) *apiError {
	body, err := io.ReadAll(io.LimitReader(c.Request.Body, 1<<20))
	if err != nil {
		return badRequest("读取请求体失败", "", "")
	}
	trimmed := bytes.TrimSpace(body)
	if len(trimmed) == 0 {
		return nil
	}

	contentType := c.GetHeader("Content-Type")
	if contentType == "" {
		return unsupportedMedia()
	}
	mediaType, _, err := mime.ParseMediaType(contentType)
	if err != nil || !strings.EqualFold(mediaType, "application/json") {
		return unsupportedMedia()
	}
	if trimmed[0] != '{' {
		return badRequest("请求体必须是 JSON 对象", "body", "INVALID_BODY")
	}
	var object map[string]json.RawMessage
	if err := json.Unmarshal(trimmed, &object); err != nil {
		return badRequest("请求体不是合法 JSON", "body", "INVALID_JSON")
	}
	if len(object) > 0 {
		field := ""
		for key := range object {
			field = key
			break
		}
		return badRequest("请求体不接受任何字段", field, "UNKNOWN_FIELD")
	}
	return nil
}

func noBodyAllowed(c *gin.Context) *apiError {
	if c.Request.Method == http.MethodGet || c.Request.Method == http.MethodDelete {
		return nil
	}
	return validateEmptyJSONBody(c)
}

package httpapi

import (
	"net/http"
	"regexp"

	"certadmin/internal/service"

	"github.com/gin-gonic/gin"
)

// Server wires the HTTP contract to the service layer.
type Server struct {
	svc          *service.Service
	engine       *gin.Engine
	exportSem    chan struct{}
	exportRowHook func(service.CertificateCSVRow, int) error
}

func New(svc *service.Service) *Server {
	s := &Server{
		svc:       svc,
		exportSem: make(chan struct{}, 2),
	}
	engine := gin.New()
	engine.HandleMethodNotAllowed = true
	engine.RedirectTrailingSlash = false
	engine.RedirectFixedPath = false
	engine.RemoveExtraSlash = false
	engine.Use(requestIDMiddleware(), recoveryMiddleware())
	engine.NoRoute(s.handleNotFound)
	engine.NoMethod(s.handleMethodNotAllowed)

	api := engine.Group("/api/v1", s.authMiddleware())
	api.GET("/me", s.handleMe)
	api.GET("/courses", s.handleCourses)
	api.GET("/courses/:courseId/enrollments", s.handleCourseEnrollments)
	api.POST("/courses/:courseId/bulk-operations", s.handleBulkIssue)
	api.GET("/learners/:learnerId/enrollments", s.handleLearnerEnrollments)
	api.GET("/certificates", s.handleCertificates)
	api.GET("/certificates.csv", s.handleCertificateCSV)
	api.GET("/certificates/:certificateId", s.handleCertificateDetail)
	api.PUT("/certificates/:certificateId/revocation", s.handleRevocation)

	s.engine = engine
	return s
}

func (s *Server) Handler() http.Handler { return s.engine }

func (s *Server) handleNotFound(c *gin.Context) {
	s.writeError(c, &apiError{Status: http.StatusNotFound, Code: "NOT_FOUND", Message: "未知 API 路径"})
}

type routeRule struct {
	pattern *regexp.Regexp
	methods []string
}

var routeRules = []routeRule{
	{regexp.MustCompile(`^/api/v1/me$`), []string{"GET"}},
	{regexp.MustCompile(`^/api/v1/courses$`), []string{"GET"}},
	{regexp.MustCompile(`^/api/v1/courses/[1-9][0-9]*/enrollments$`), []string{"GET"}},
	{regexp.MustCompile(`^/api/v1/courses/[1-9][0-9]*/bulk-operations$`), []string{"POST"}},
	{regexp.MustCompile(`^/api/v1/learners/[1-9][0-9]*/enrollments$`), []string{"GET"}},
	{regexp.MustCompile(`^/api/v1/certificates$`), []string{"GET"}},
	{regexp.MustCompile(`^/api/v1/certificates\.csv$`), []string{"GET"}},
	{regexp.MustCompile(`^/api/v1/certificates/[1-9][0-9]*$`), []string{"GET"}},
	{regexp.MustCompile(`^/api/v1/certificates/[1-9][0-9]*/revocation$`), []string{"PUT"}},
}

func (s *Server) handleMethodNotAllowed(c *gin.Context) {
	for _, rule := range routeRules {
		if rule.pattern.MatchString(c.Request.URL.Path) {
			c.Header("Allow", rule.methods[0])
			s.writeError(c, &apiError{
				Status:  http.StatusMethodNotAllowed,
				Code:    "METHOD_NOT_ALLOWED",
				Message: "该路径不支持此 HTTP 方法",
			})
			return
		}
	}
	s.handleNotFound(c)
}

