import { chromium } from 'playwright'

const base = 'http://127.0.0.1:18085'
const browser = await chromium.launch()
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } })
const errors = []
page.on('pageerror', (err) => errors.push(`pageerror: ${err.message}`))
page.on('console', (msg) => {
  if (msg.type() === 'error') errors.push(`console: ${msg.text()}`)
})

const listRequests = []
page.on('request', (req) => {
  if (req.url().includes('/api/v1/certificates?')) listRequests.push(req.url())
})

function check(condition, message) {
  if (!condition) throw new Error(message)
}

async function switchTo(label, tenantText) {
  await page.locator('.actor-select').click()
  await page.locator('.el-select-dropdown__item', { hasText: label }).last().click()
  await page.getByText(tenantText).waitFor({ timeout: 5000 })
  await page.waitForTimeout(600)
}

async function rowsText() {
  return await page.locator('.cert-table').innerText()
}

async function selectCourse() {
  await page.locator('.filter-select').nth(1).click()
  await page.locator('.el-select-dropdown__item', { hasText: 'Safety 101' }).last().click()
  await page.waitForTimeout(500)
}

await page.route('**/api/v1/certificates?*', async (route) => {
  const auth = route.request().headers()['authorization'] ?? ''
  if (auth.includes('demo-alice-token')) {
    try {
      const response = await route.fetch()
      await new Promise((resolve) => setTimeout(resolve, 1200))
      await route.fulfill({ response })
    } catch {
      // The AbortController may have cancelled the request; nothing to deliver.
    }
  } else {
    await route.continue()
  }
})

await page.goto(base, { waitUntil: 'networkidle' })
await page.getByText('CERT-EAST-TAYLOR-0001').first().waitFor()

// 1) A delayed Alice response must not overwrite Bob's UI.
await page.getByRole('button', { name: '查询' }).click()
await switchTo('Bob · West', 'West · Australia/Perth')
await page.waitForTimeout(1400)
let text = await rowsText()
check(text.includes('CERT-WEST-TAYLOR-0001'), 'Bob data missing after stale Alice response')
check(!text.includes('CERT-EAST-'), `stale Alice response leaked into Bob UI:\n${text}`)
await page.unroute('**/api/v1/certificates?*')

// 2) Switching tenant must clear the selected course filter.
await switchTo('Alice · East', 'East · Australia/Sydney')
await selectCourse()
check((await rowsText()).includes('CERT-EAST-TAYLOR-0001'), 'East course filter did not load')
check(listRequests.at(-1)?.includes('courseId=1'), 'courseId was not sent while selected')

await switchTo('Bob · West', 'West · Australia/Perth')
text = await rowsText()
check(text.includes('CERT-WEST-TAYLOR-0001'), 'West list is empty after tenant switch')
check(!text.includes('CERT-EAST-'), 'East row survived tenant switch')
check(!(listRequests.at(-1) ?? '').includes('courseId='), `courseId survived tenant switch: ${listRequests.at(-1)}`)
const courseValue = await page.locator('.filter-select').nth(1).locator('input').inputValue()
check(courseValue === '', `course select still shows ${courseValue}`)

// 3) Clearing a select must not send an undefined/empty parameter.
await switchTo('Alice · East', 'East · Australia/Sydney')
await selectCourse()
const courseSelect = page.locator('.filter-select').nth(1)
await courseSelect.hover()
await courseSelect.locator('.el-select__clear').click()
await page.waitForTimeout(600)
check(!(listRequests.at(-1) ?? '').includes('courseId'), `cleared course still sent: ${listRequests.at(-1)}`)
check((await rowsText()).includes('CERT-EAST-TAYLOR-0001'), 'clearing course filter lost rows')

const statusSelect = page.locator('.filter-select').nth(0)
await statusSelect.click()
await page.locator('.el-select-dropdown__item', { hasText: '有效 ACTIVE' }).last().click()
await page.waitForTimeout(500)
check((listRequests.at(-1) ?? '').includes('status=ACTIVE'), 'status filter was not sent')
await statusSelect.hover()
await statusSelect.locator('.el-select__clear').click()
await page.waitForTimeout(600)
check(!(listRequests.at(-1) ?? '').includes('status='), `cleared status still sent: ${listRequests.at(-1)}`)

// 4) A delayed detail response must not appear after switching tenant.
await page.route('**/api/v1/certificates/3', async (route) => {
  try {
    const response = await route.fetch()
    await new Promise((resolve) => setTimeout(resolve, 1200))
    await route.fulfill({ response })
  } catch {
    // Aborted by the tenant switch.
  }
})
await page.getByText('CERT-EAST-TAYLOR-0001').first().click()
await switchTo('Bob · West', 'West · Australia/Perth')
await page.waitForTimeout(1400)
check((await page.getByText('证书详情').count()) === 0, 'detail drawer stayed visible after tenant switch')
check((await page.locator('body').innerText()).includes('CERT-WEST-TAYLOR-0001'), 'Bob list missing after stale detail')
await page.unroute('**/api/v1/certificates/3')

// 5) The issuance dialog must not keep a course id across tenant switches.
await switchTo('Alice · East', 'East · Australia/Sydney')
await page.getByRole('button', { name: '批量发证' }).click()
await page.locator('.issue-course').click()
await page.locator('.el-select-dropdown__item', { hasText: 'Safety 101（#1）' }).last().click()
await page.getByText('课程未完成').first().waitFor()
await page.getByRole('button', { name: '关闭', exact: true }).click()
await switchTo('Bob · West', 'West · Australia/Perth')
await page.getByRole('button', { name: '批量发证' }).click()
const issueValue = await page.locator('.issue-course input').inputValue()
check(issueValue === '', `issuance course id survived tenant switch: ${issueValue}`)
await page.getByRole('button', { name: '关闭', exact: true }).click()

if (errors.length > 0) throw new Error(errors.join('\n'))
console.log('frontend regression passed')
console.log(JSON.stringify({ requests: listRequests.length }))
await browser.close()

