input.content:
import { chromium } from 'playwright'

const base = 'http://127.0.0.1:18087'
const browser = await chromium.launch()
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } })
const errors = []
page.on('pageerror', (err) => errors.push(`pageerror: ${err.message}`))
page.on('console', (msg) => {
  if (msg.type() === 'error') errors.push(`console: ${msg.text()}`)
})

function check(condition, message) {
  if (!condition) throw new Error(message)
}

async function openIssueAndSelectCourse() {
  await page.getByRole('button', { name: '批量发证' }).click()
  await page.locator('.issue-course').click()
  await page.locator('.el-select-dropdown__item', { hasText: 'Safety 101（#1）' }).last().click()
  await page.getByText('课程未完成').first().waitFor()
}

await page.route('**/api/v1/courses/1/bulk-operations', async (route) => {
  try {
    const response = await route.fetch()
    await new Promise((resolve) => setTimeout(resolve, 1500))
    await route.fulfill({ response })
  } catch {
    // Closing the dialog aborts the old request; that is expected.
  }
})

await page.goto(base, { waitUntil: 'networkidle' })
await page.getByText('CERT-EAST-TAYLOR-0001').first().waitFor()

// Start an issuance, then close the dialog while the response is delayed.
await openIssueAndSelectCourse()
await page.getByRole('button', { name: '发起批量发证' }).click()
await page.waitForTimeout(300)
await page.getByRole('button', { name: '关闭', exact: true }).click()
await page.locator('.el-dialog').waitFor({ state: 'hidden', timeout: 5000 })

// Reopen with the same actor and the same course. The old response arrives
// after this point and must not populate the new dialog.
await openIssueAndSelectCourse()
await page.waitForTimeout(1800)

const dialogText = await page.locator('.el-dialog').innerText()
check(!dialogText.includes('操作结果'), `old result was written into the reopened dialog:\n${dialogText}`)
check((await page.locator('.result-block').count()) === 0, 'result block exists in reopened dialog')
const submit = page.getByRole('button', { name: '发起批量发证' })
check(await submit.isEnabled(), 'submit button stayed disabled by an old response')

// The reopened dialog must still be usable for a genuinely new operation.
await page.unroute('**/api/v1/courses/1/bulk-operations')
await submit.click()
await page.getByText('操作结果').waitFor({ timeout: 10000 })

if (errors.length > 0) throw new Error(errors.join('\n'))
console.log('issue-dialog attempt regression passed')
await browser.close()
